const disableAll = [];
function selectArgs(table, disableAll) {
  const labels = location.hostname.toLowerCase().split(".");
  const hosts = [];
  for (let i = 0; i < labels.length; i++) {
    hosts.push(labels.slice(i).join("."));
    // entity forms: "a.b.site.co.uk" also matches "site.*" (suffix of one or two labels)
    for (let r = 1; r <= 2; r++) if (labels.length - i > r) hosts.push(labels.slice(i, labels.length - r).join(".") + ".*");
  }
  if (hosts.some((h) => disableAll.includes(h))) return [];
  const excluded = new Set();
  for (const h of hosts) for (const i of table.exclude[h] || []) excluded.add(i);
  const chosen = new Set();
  for (const h of hosts) for (const i of table.include[h] || []) if (!excluded.has(i)) chosen.add(i);
  return [...chosen].map((i) => table.args[i]);
}
function makeNeedle(spec) {
  let s = String(spec ?? "");
  let invert = false;
  if (s.startsWith("!")) {
    invert = true;
    s = s.slice(1);
  }
  let test;
  if (s === "") test = () => true;
  else {
    const m = /^\/(.+)\/([gimsu]*)$/.exec(s);
    const re = m ? new RegExp(m[1], m[2].replace("g", "")) : null;
    test = re ? (t) => re.test(t) : (t) => t.includes(s);
  }
  return (text) => test(String(text)) !== invert;
}

function abortCurrentScript(chain, needle) {
  if (!chain) return;
  const matches = makeNeedle(needle);
  const magic = "LocalBlock-" + Math.random().toString(36).slice(2);
  const parts = chain.split(".");
  const last = parts.pop();
  let owner = window;
  for (const p of parts) {
    owner = owner?.[p];
    if (owner === null || owner === undefined) return;
  }
  const desc = Object.getOwnPropertyDescriptor(owner, last);
  if (desc && desc.configurable === false) return;
  let value = owner[last];
  const getter = desc && desc.get;
  const setter = desc && desc.set;
  const shouldAbort = () => {
    const script = document.currentScript;
    if (!script) return false;
    const text = script.src ? script.src : script.textContent || "";
    return matches(text);
  };
  try {
    Object.defineProperty(owner, last, {
      configurable: true,
      get() {
        if (shouldAbort()) throw new ReferenceError(magic);
        return getter ? getter.call(this) : value;
      },
      set(v) {
        if (shouldAbort()) throw new ReferenceError(magic);
        if (setter) setter.call(this, v);
        else value = v;
      },
    });
  } catch {}
}

for (const args of selectArgs(table, disableAll)) {
  try { abortCurrentScript(...args); } catch (e) { /* a broken filter must not break the page */ }
}
